export function LongPress({
  held = {{held}},
  duration = {{duration}},
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 18, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      <button type="button" style={{ border: "none", background: "transparent", cursor: "pointer", padding: 0 }}>
        <svg viewBox="0 0 44 44" width="44" height="44" aria-hidden="true">
          <circle cx="22" cy="22" r="18" fill="none" stroke="#24143022" strokeWidth="4" />
          <circle className="ring" cx="22" cy="22" r="18" fill="none" stroke={accent} strokeWidth="4" strokeDasharray="113.1" style={{ strokeDashoffset: held ? 0 : 113.1, transform: "rotate(-90deg)", transformOrigin: "50% 50%" }} />
        </svg>
      </button>
      <p style={{ margin: "12px 0 0" }}>{label} &mdash; ring fills over {duration}ms of holding, {held ? "completed" : "released early"}</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .ring { transition: stroke-dashoffset ${duration}ms linear; }
        }
      `}</style>
    </div>
  );
}
